		.order(noarr::slice<'k'>(1, n - 1))
		.template for_dims<'k'>([&](auto k_trav) {
			auto k_state = k_trav.state();
			auto k = noarr::get_index<'k'>(k_state);

			// beta = (1 - alpha * alpha) * beta;
			beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;

			// sum = 0.0;
			sum = SCALAR_VAL(0.0);

			// sum = sum_{i=0}^{k-1} r[k - i - 1] * y[i];
			noarr::traverser(y, r)
				.order(noarr::slice<'i'>(0, k))
				.for_each([&](auto ir_state) {
					auto i = noarr::get_index<'i'>(ir_state);

					auto r_state = noarr::idx<'i'>(k - i - 1);
					sum += r[r_state] * y[ir_state];
				});

			// alpha = - (r[k] + sum) / beta;
			alpha = -(r[noarr::idx<'i'>(k)] + sum) / beta;

			/*
			 * Original code:
			 *   for (i = 0; i < k; i++) z[i] = y[i] + alpha * y[k - i - 1];
			 *   for (i = 0; i < k; i++) y[i] = z[i];
			 *
			 * This computes:
			 *   y_new[i] = y_old[i] + alpha * y_old[k - i - 1]
			 *
			 * We can do this in-place without the temporary z by processing
			 * symmetric index pairs (i, j = k-1-i) at once:
			 *   new_i = old_i + alpha * old_j
			 *   new_j = old_j + alpha * old_i
			 *
			 * For k even, all indices form disjoint pairs.
			 * For k odd, there is one central index i == j; we then apply the
			 * same update twice, which is harmless.
