// computation kernel
// Optimized to:
//  - eliminate the temporary vector z by doing an in-place, pairwise update of y
//  - reduce memory traffic and improve cache behavior
//  - keep all loop nests expressed via Noarr traversers
[[gnu::flatten, gnu::noinline]]
void kernel_durbin(auto r, auto y) {
	using namespace noarr;

	// length of the 1D vectors
	auto n = r | get_length<'i'>();

	// pseudo-structure for the k loop: k in [0, n)
	auto k_structure = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

	num_t alpha;
	num_t beta;
	num_t sum;

	#pragma scop
	// Initial step: k = 0
	auto i0 = noarr::idx<'i'>(0);
	y[i0] = -r[i0];
	beta = SCALAR_VAL(1.0);
	alpha = -r[i0];

	// Main Durbin recursion: k = 1 .. n-1
	noarr::traverser(k_structure)
		// Restrict to logical k in [1, n-1].
		// Thanks to `order(slice)`, the states we obtain still carry
		// original k-indices (1 .. n-1), just the range is restricted.
		.order(noarr::slice<'k'>(1, n - 1))
		.template for_dims<'k'>([&](auto k_trav) {
			auto k_state = k_trav.state();
			std::size_t k = noarr::get_index<'k'>(k_state); // 1 <= k < n

			// beta = (1 - alpha * alpha) * beta;
			beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;

			// sum = 0.0;
			sum = SCALAR_VAL(0.0);

			// sum = Σ_{i=0}^{k-1} r[k - i - 1] * y[i];
			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, k)) // i = 0..k-1
				.for_each([&](auto yi_state) {
					std::size_t i = noarr::get_index<'i'>(yi_state);
					auto r_state  = noarr::idx<'i'>(k - i - 1);
					sum += r[r_state] * y[yi_state];
				});

			// alpha = - (r[k] + sum) / beta;
			alpha = -(r[noarr::idx<'i'>(k)] + sum) / beta;

			// In the original code:
			//   z[i] = y[i] + alpha * y[k - i - 1];
			//   y[i] = z[i];
			//
			// This requires an auxiliary vector z. Here we avoid z by
			// updating y in-place, using the symmetry of indices:
			//   pair (i, j) with j = k - i - 1
			//
			// For such a pair, based on the original formulation:
			//   y_new[i] = y_old[i] + alpha * y_old[j];
			//   y_new[j] = y_old[j] + alpha * y_old[i];
			//
			// If we process pairs (i, j) with i < j, read both old
			// values first, and then write both results, we never
			// read an already updated value. The center element in
			// case of odd k is handled separately.

			std::size_t half = k / 2; // number of disjoint (i, j) pairs with i < j

			// Update all disjoint pairs (i, j = k - i - 1), i < j
			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, half)) // i = 0..half-1
				.for_each([&](auto yi_state) {
					std::size_t i = noarr::get_index<'i'>(yi_state);
					std::size_t j = k - i - 1; // j > i for all i in this range

					auto i_state = noarr::idx<'i'>(i);
					auto j_state = noarr::idx<'i'>(j);

					num_t yi = y[i_state];
					num_t yj = y[j_state];

					// Both new values depend only on the original pair (yi, yj)
					y[i_state] = yi + alpha * yj;
					y[j_state] = yj + alpha * yi;
				});

			// If k is odd, there is a middle index mid = k/2 where i == j.
			// For this index the update reduces to:
			//   y[mid] = y[mid] + alpha * y[mid] = (1 + alpha) * y[mid].
			if (k % 2u != 0u) {
				std::size_t mid = k / 2u;
				auto mid_state  = noarr::idx<'i'>(mid);
				num_t ym        = y[mid_state];
				y[mid_state]    = ym + alpha * ym;
			}

			// y[k] = alpha;
			y[noarr::idx<'i'>(k)] = alpha;
		});
	#pragma endscop
